/bin/zsh -lc "node --input-type=module <<'NODE'
import { readFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
// 临时复核脚本仅采集受管区块外文本的摘要，不写入项目。
const hash = text => createHash('sha256').update(text).digest('hex');
const blocks = {
  'AGENTS.md': ['deep-guardrails'],
  'wayfinder/frontend.md': ['meta', 'scope', 'analysis'],
  'openspec/config.yaml': ['root'],
};
const preserved = {};
for (const [file, names] of Object.entries(blocks)) {
  let text = readFileSync(file, 'utf8');
  for (const name of names) {
    const pattern = name === 'root'
      ? /"'^# frontend-ai-workflow:start[''^'"\\n]*\\n[\\s\\S]*?"'^# frontend-ai-workflow:end/gm
      : new RegExp(`<!-- frontend-ai-workflow:${name}:start[''^>]*-->['"\\\\s\\\\S]*?<"'!-- frontend-ai-workflow:${name}:end -->`, '"'g');
    const matches = [...text.matchAll(pattern)];
    if (matches.length "'!== 1) throw new Error(`${file} 的 ${name} 标记必须唯一配对`);
    text = text.replace(pattern, `[受管:${name}]`);
  }
  preserved[file] = hash(text);
}
console.log(JSON.stringify(preserved));
NODE'

/bin/zsh -lc "node --input-type=module <<'NODE'
import { readFileSync, writeFileSync } from 'node:fs';
// 临时同步脚本只更新地图完成合同，不改动扫描快照。
const file = 'wayfinder/frontend.md';
const source = readFileSync(file, 'utf8');
const now = new Date().toISOString();
const pattern = /<"'!-- frontend-ai-workflow:meta:start[''^>]*-->['"\\s\\S]*?<"'!-- frontend-ai-workflow:meta:end -->/g;
if ([...source.matchAll(pattern)].length !== 1) throw new Error('"'meta 标记必须唯一配对');
const updated = source.replace(pattern, block => block
  .replace(/"'^analysisStatus: "pending"$/m, '"'analysisStatus: \"complete\"')
  .replace(/"'^analysisCoveredFiles: 0$/m, '"'analysisCoveredFiles: 15')
  .replace(/"'^analysisUpdatedAt: "未完成"$/m, `analysisUpdatedAt: "${now}"`));
if (updated === source || !updated.includes('"'analysisStatus: \"complete\"')) throw new Error('地图状态未同步');
writeFileSync(file, updated);
console.log(JSON.stringify({analysisStatus: 'complete', analysisCoveredFiles: 15, analysisUpdatedAt: now}));
NODE"

